------------ import ------------
local KTool = CS.Engine.Lib.KTool
------------ import ------------
local TreasureNodeLuaPath = "Game.UI.UIBattling.UIBattlingTreasureNode"
local QualityOrderMap = {
    [1] = 3,    -- 铜宝箱
    [2] = 2,    -- 银宝箱
    [3] = 1,    -- 金宝箱
}

--- from: Assets/BundleResources/Prefabs/UIBattling/UIBattingTreasureChestNode.prefab
---@class UIBattlingTreasureGroup
---@field Env                           	UIBattlingTreasureGroup                                     
---@field controller                    	Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field RT_TreasureInstance           	UnityEngine.RectTransform               
---@field RT_TreasureRoot               	UnityEngine.RectTransform               

local UIBattlingTreasureGroup = Class("UIBattlingTreasureGroup")

function UIBattlingTreasureGroup:__init()
    self:CleanField()
end

function UIBattlingTreasureGroup:__delete()
    self:CleanField()
    self.controller = nil
    self = nil
end

function UIBattlingTreasureGroup:CleanField()
    self.treasureLTMap = nil
end

function UIBattlingTreasureGroup:Awake()
    self.treasureLTMap = {}
end

function UIBattlingTreasureGroup:OnDestroy()
    self.controller = nil
    --luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

function UIBattlingTreasureGroup:AddTreasure(quality, num)
    local has = isSet(self.treasureLTMap, quality)
    local LT_Treasure = self.treasureLTMap[quality]
    if not has then
        -- 实例化宝箱节点
        local treasure =  KTool.Instantiate(self.RT_TreasureRoot.gameObject, self.RT_TreasureInstance.gameObject)
        local LB_Treasure = GetLuaBehaviour(treasure, TreasureNodeLuaPath)
        LB_Treasure:Init()
        LT_Treasure = LB_Treasure.Env
        self.treasureLTMap[quality] = LT_Treasure
        local order = QualityOrderMap[quality]
        LT_Treasure:SetQuality(order)
        treasure.transform:SetSiblingIndex(order);
        KTool.SetActive(treasure, true)
    end
    LT_Treasure:AddNum(num)
end

return UIBattlingTreasureGroup
